260	Token Lexer::scanPunctuation() {
261	    int l = line_, c = col_;
262	    char ch = advance();
263	
264	    auto make = [&](TokenKind k, std::string v) {
265	        return makeToken(k, std::move(v), l, c);
266	    };
267	
268	    switch (ch) {
269	        case '(': return make(TokenKind::LParen,     "(");
270	        case ')': return make(TokenKind::RParen,     ")");
271	        case '{': return make(TokenKind::LBrace,     "{");
272	        case '}': return make(TokenKind::RBrace,     "}");
273	        case '[': return make(TokenKind::LBracket,   "[");
274	        case ']': return make(TokenKind::RBracket,   "]");
275	        case ';': return make(TokenKind::Semicolon,  ";");
276	        case ':': return make(TokenKind::Colon,      ":");
277	        case ',': return make(TokenKind::Comma,      ",");
278	        case '~': return make(TokenKind::Tilde,      "~");
279	        case '^': return make(TokenKind::Caret,      "^");
280	        case '%': {
281	            if (peek() == '=') { advance(); return make(TokenKind::PercentEquals, "%="); }
282	            return make(TokenKind::Percent, "%");
283	        }
284	        case '?': {
285	            if (peek() == '?') { advance(); return make(TokenKind::QuestionQuestion, "??"); }
286	            return make(TokenKind::QuestionMark, "?");
287	        }
288	        case '.': {
289	            if (peek() == '.' && peek(1) == '.') {
290	                advance(); advance(); return make(TokenKind::DotDotDot, "...");
291	            }
292	            return make(TokenKind::Dot, ".");
293	        }
294	        case '=': {
295	            if (peek() == '>') { advance(); return make(TokenKind::Arrow, "=>"); }
296	            if (peek() == '=') {
297	                advance();
298	                if (peek() == '=') { advance(); return make(TokenKind::EqualsEqualsEquals, "==="); }
299	                return make(TokenKind::EqualsEquals, "==");
300	            }
301	            return make(TokenKind::Equals, "=");
302	        }
303	        case '!': {
304	            if (peek() == '=') {
305	                advance();
306	                if (peek() == '=') { advance(); return make(TokenKind::BangEqualsEquals, "!=="); }
307	                return make(TokenKind::BangEquals, "!=");
308	            }
309	            return make(TokenKind::Bang, "!");
310	        }
311	        case '<': {
312	            if (jsxAllowed()) return make(TokenKind::JSXLess, "<");
313	            if (peek() == '<') { advance(); return make(TokenKind::LShift, "<<"); }
314	            if (peek() == '=') { advance(); return make(TokenKind::LessEquals, "<="); }
315	            return make(TokenKind::Less, "<");
316	        }
317	        case '>': {
318	            if (peek() == '>') {
319	                advance();
320	                if (peek() == '>') { advance(); return make(TokenKind::URShift, ">>>"); }
321	                return make(TokenKind::RShift, ">>");
322	            }
323	            if (peek() == '=') { advance(); return make(TokenKind::GreaterEquals, ">="); }
324	            return make(TokenKind::Greater, ">");
325	        }
326	        case '+': {
327	            if (peek() == '+') { advance(); return make(TokenKind::PlusPlus, "++"); }
328	            if (peek() == '=') { advance(); return make(TokenKind::PlusEquals, "+="); }
329	            return make(TokenKind::Plus, "+");
330	        }
331	        case '-': {
332	            if (peek() == '-') { advance(); return make(TokenKind::MinusMinus, "--"); }
333	            if (peek() == '=') { advance(); return make(TokenKind::MinusEquals, "-="); }
334	            return make(TokenKind::Minus, "-");
335	        }
336	        case '*': {
337	            if (peek() == '=') { advance(); return make(TokenKind::StarEquals, "*="); }
338	            return make(TokenKind::Star, "*");
339	        }
340	        case '/': {
341	            if (regexAllowed()) return scanRegex(l, c);
342	            if (peek() == '=') { advance(); return make(TokenKind::SlashEquals, "/="); }
343	            return make(TokenKind::Slash, "/");
344	        }
345	        case '&': {
346	            if (peek() == '&') { advance(); return make(TokenKind::AmpAmp, "&&"); }
347	            return make(TokenKind::Amp, "&");
348	        }
349	        case '|': {
350	            if (peek() == '|') { advance(); return make(TokenKind::PipePipe, "||"); }
351	            return make(TokenKind::Pipe, "|");
352	        }
353	        default:
354	            return make(TokenKind::Unknown, std::string(1, ch));
355	    }
356	}
