// Main tokenise loop
//
// The lexer self-manages the JSX mode stack as it emits tokens:
//
//   JSXLess emitted (JS mode)  -> push JSXTag
//   JSXGreater emitted (tag)   -> pop JSXTag, push JSXChildren
//   JSXSlashGreater emitted    -> pop JSXTag          (self-closing)
//   JSXLessSlash emitted       -> pop JSXChildren, push JSXTag (closing tag)
//   JSXGreater emitted (close) -> pop JSXTag          (closing tag done)
//   LBrace in JSXChildren      -> push JS
//   RBrace in JS, parent=jsx   -> pop JS, back to JSXChildren
//
// A small "brace depth" counter inside each JS-inside-JSX context lets us
// pop back to JSXChildren after the matching }.  We track this with a
// parallel stack of brace depths.
// ---------------------------------------------------------------------------
std::vector<Token> Lexer::tokenize() {
    std::vector<Token> tokens;

    // Each entry on jsxBraceDepth corresponds to one JS-inside-JSX expression.
    // When we push JS mode from JSXChildren we record the current JS brace
    // depth; when it returns to that depth and we see } we pop back.
    std::vector<int> jsxBraceDepth;
    int braceDepth = 0; // tracks { } in JS mode

    while (true) {
        // In JSXChildren we do NOT skip whitespace — it may be JSXText.
        if (currentMode() != LexMode::JSXChildren)
            skipWhitespaceAndComments();

        if (atEnd()) {
            tokens.push_back(makeToken(TokenKind::EndOfFile, "", line_, col_));
            break;
        }

        LexMode mode = currentMode();
        Token   tok;

        // ----------------------------------------------------------------
        // JSXChildren mode: raw text, { expr }, or nested < tag
        // ----------------------------------------------------------------
        if (mode == LexMode::JSXChildren) {
            char ch = peek();

            if (ch == '<') {
                int l = line_, c = col_;
                advance();
                if (peek() == '/') {
                    advance();
                    tok = makeToken(TokenKind::JSXLessSlash, "</", l, c);
                    // closing tag: swap children -> tag
                    popMode();
                    pushMode(LexMode::JSXTag);
                } else {
                    tok = makeToken(TokenKind::JSXLess, "<", l, c);
                    // nested opening tag
                    pushMode(LexMode::JSXTag);
                }
            } else if (ch == '{') {
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::LBrace, "{", l, c);
                // Enter JS expression inside JSX; remember brace depth to pop back
                jsxBraceDepth.push_back(braceDepth);
                pushMode(LexMode::JS);
            } else {
                // Skip leading whitespace manually so we can still detect empty text
                tok = scanJSXText();
                // Suppress pure-whitespace JSXText tokens — parser already
                // filters them, but emitting them cleans up the stream too.
                if (tok.value.empty()) continue;
            }

        // ----------------------------------------------------------------
        // JSXTag mode: tag name, attributes, /> or >
        // ----------------------------------------------------------------
        } else if (mode == LexMode::JSXTag) {
            skipWhitespaceAndComments();
            char ch = peek();

            if (ch == '/' && peek(1) == '>') {
                int l = line_, c = col_;
                advance(); advance();
                tok = makeToken(TokenKind::JSXSlashGreater, "/>", l, c);
                popMode(); // back to wherever we came from (JS or JSXChildren)
            } else if (ch == '>') {
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::JSXGreater, ">", l, c);
                // Replace JSXTag with JSXChildren — unless this was a closing
                // tag (detected by the previous JSXLessSlash token).
                if (lastKind_ == TokenKind::JSXLessSlash || lastKind_ == TokenKind::Identifier) {
                    // closing tag just finished: pop JSXTag (already pushed by JSXLessSlash handler)
                    // and we're back to the parent JSXChildren or JS context.
                    popMode();
                } else {
                    // opening tag: switch JSXTag -> JSXChildren
                    popMode();
                    pushMode(LexMode::JSXChildren);
                }
            } else if (ch == '{') {
                // spread attribute: {...x}
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::LBrace, "{", l, c);
                jsxBraceDepth.push_back(braceDepth);
                pushMode(LexMode::JS);
            } else if (ch == '"' || ch == '\'') {
                tok = scanJSXString(ch);
            } else if (ch == '.' && peek(1) == '.' && peek(2) == '.') {
                int l = line_, c = col_;
                advance(); advance(); advance();
                tok = makeToken(TokenKind::DotDotDot, "...", l, c);
            } else if (ch == '.') {
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::Dot, ".", l, c);
            } else if (ch == '=') {
                int l = line_, c = col_;
                advance();
                tok = makeToken(TokenKind::Equals, "=", l, c);
            } else if (std::isalpha(static_cast<unsigned char>(ch)) || ch == '_') {
                tok = scanIdentifierOrKeyword();
                tok.kind = TokenKind::Identifier; // keywords are just names in JSX tags
            } else {
                tok = makeToken(TokenKind::Unknown, std::string(1, advance()), line_, col_);
            }

        // ----------------------------------------------------------------
        // JS mode (default)
        // ----------------------------------------------------------------
        } else {
            char ch = peek();

            // Track brace depth so we know when a JS-inside-JSX expr ends.
            if (ch == '{') {
                ++braceDepth;
            } else if (ch == '}') {
                if (!jsxBraceDepth.empty() && braceDepth == jsxBraceDepth.back() + 1) {
                    // This } closes the JSX expression container.
                    int l = line_, c = col_;
                    advance();
                    tok = makeToken(TokenKind::RBrace, "}", l, c);
                    jsxBraceDepth.pop_back();
                    popMode(); // back to JSXChildren or JSXTag
                    lastKind_ = tok.kind;
                    tokens.push_back(std::move(tok));
                    continue;
                }
                --braceDepth;
            }

            if (std::isdigit(static_cast<unsigned char>(ch))) {
                tok = scanNumber();
            } else if (ch == '"' || ch == '\'') {
                tok = scanString(ch);
            } else if (ch == '`') {
                tok = scanTemplate();
            } else if (std::isalpha(static_cast<unsigned char>(ch)) || ch == '_' || ch == '$') {
                tok = scanIdentifierOrKeyword();
            } else {
                tok = scanPunctuation();
            }
        }

        lastKind_ = tok.kind;
        tokens.push_back(std::move(tok));
    }

    return tokens;
}

