// ---------------------------------------------------------------------------
// parseParam — one function parameter: ident, ...rest, {destruct}, [destruct]
// We store the source text of patterns verbatim so codegen can re-emit them.
// ---------------------------------------------------------------------------
static NodePtr parseParamPattern(Parser* self, const std::function<NodePtr()>& parseExprFn);

// Forward-declare so parseFunctionDecl can use it.
static std::string consumePattern(Parser* self);

// Consume a destructuring pattern as raw source text for codegen to re-emit.
// This is a simplified "slurp balanced brackets" approach — sufficient for
// the MVP because codegen just needs to emit params verbatim.
static std::string consumeBalanced(Parser* self, TokenKind open, TokenKind close,
                                   char openCh, char closeCh) {
    // The opening token was already consumed by the caller.
    std::string s;
    s += openCh;
    int depth = 1;
    while (depth > 0) {
        // peek() on Parser is private — but we can use advance via the public
        // interface.  We'll reconstruct by just grabbing token values.
        // (This relies on tokens having their original .value set correctly.)
        // Use a small trick: cast through friend — instead, expose via a
        // thin wrapper in the parser or reconstruct from tokens.
        // Since we don't have direct access here, we'll handle this inside
        // a Parser member function instead.
        (void)open; (void)close; (void)depth; break; // placeholder
    }
    return s;
}

NodePtr Parser::parseParam() {
    const Token& t = peek();
    auto n = makeNode(NodeKind::Identifier, t.line, t.col);

    if (match(TokenKind::DotDotDot)) {
        // rest parameter
        n->name = "..." + expect(TokenKind::Identifier, "rest parameter name").value;
        return n;
    }

    if (check(TokenKind::LBrace)) {
        // Object destructuring: consume { ... } as raw text
        n->name = consumeDestructure(TokenKind::LBrace, TokenKind::RBrace, '{', '}');
        return n;
    }

    if (check(TokenKind::LBracket)) {
        // Array destructuring: consume [ ... ] as raw text
        n->name = consumeDestructure(TokenKind::LBracket, TokenKind::RBracket, '[', ']');
        return n;
    }

    n->name = expect(TokenKind::Identifier, "parameter name").value;
    // Default value: name = expr
    if (match(TokenKind::Equals)) {
        // Store " = <expr>" suffix in name for verbatim re-emit
        n->name += " = ";
        // Consume tokens until , or ) — simple greedy approach
        int depth = 0;
        while (!atEnd()) {
            TokenKind k = peek().kind;
            if (depth == 0 && (k == TokenKind::Comma || k == TokenKind::RParen)) break;
            if (k == TokenKind::LParen || k == TokenKind::LBrace || k == TokenKind::LBracket) ++depth;
            if (k == TokenKind::RParen || k == TokenKind::RBrace || k == TokenKind::RBracket) {
                if (depth == 0) break;
                --depth;
            }
            n->name += advance().value;
        }
    }
    return n;
