// Consume a balanced bracket group and return it as a string (e.g. "{ a, b }").
std::string Parser::consumeDestructure(TokenKind open, TokenKind close,
                                        char openCh, char closeCh) {
    expect(open, std::string(1, openCh));
    std::string s;
    s += openCh;
    int depth = 1;
    while (!atEnd() && depth > 0) {
        TokenKind k = peek().kind;
        if (k == open)  ++depth;
        if (k == close) { --depth; if (depth == 0) { advance(); break; } }
        s += advance().value;
        // Add spacing around commas for readability
        if (k == TokenKind::Comma) s += ' ';
    }
    s += closeCh;
    return s;
}

NodePtr Parser::parseFunctionDecl(bool isAsync) {
    const Token& start = expect(TokenKind::KW_function, "function");
    auto n = makeNode(NodeKind::FunctionDecl, start.line, start.col);
    n->async_ = isAsync;
    if (check(TokenKind::Identifier)) n->name = advance().value;
    expect(TokenKind::LParen, "(");
    while (!check(TokenKind::RParen) && !atEnd()) {
        n->params.push_back(parseParam());
        if (!match(TokenKind::Comma)) break;
    }
    expect(TokenKind::RParen, ")");
    n->body.push_back(parseBlockStmt());
    return n;
}

