// Normalise JSX text: collapse whitespace runs to single spaces.
// Only strip leading/trailing space if those ends are newlines
// (i.e. the text node is on its own line), so "Hello, " retains
// the trailing space that separates it from an adjacent expression.
std::string CodeGen::escapeJSXText(const std::string& raw) {
    std::string s;
    bool prevSpace = true; // start true to eat leading whitespace
    for (char c : raw) {
        if (std::isspace((unsigned char)c)) {
            if (!prevSpace) { s += ' '; prevSpace = true; }
        } else {
            s += c;
            prevSpace = false;
        }
    }
