// Consume a balanced bracket group and return it as a string (e.g. "{ a, b }").
std::string Parser::consumeDestructure(TokenKind open, TokenKind close,
                                        char openCh, char closeCh) {
    expect(open, std::string(1, openCh));
    std::string s;
    s += openCh;
    s += ' '; // space after opening bracket: { a, b }
    int depth = 1;
    while (!atEnd() && depth > 0) {
        TokenKind k = peek().kind;
        if (k == open)  ++depth;
        if (k == close) { --depth; if (depth == 0) { advance(); break; } }
        s += advance().value;
        if (k == TokenKind::Comma) s += ' '; // space after comma
    }
    s += ' '; // space before closing bracket
    s += closeCh;
    return s;
}

