// Consume a balanced bracket group and return it as a string.
// Uses inner spaces for object patterns "{ a, b }" but not array "[a, b]".
std::string Parser::consumeDestructure(TokenKind open, TokenKind close,
                                        char openCh, char closeCh) {
    expect(open, std::string(1, openCh));
    bool isObject = (openCh == '{');
    std::string s;
    s += openCh;
    if (isObject) s += ' ';
    int depth = 1;
    while (!atEnd() && depth > 0) {
        TokenKind k = peek().kind;
        if (k == open)  ++depth;
        if (k == close) { --depth; if (depth == 0) { advance(); break; } }
        s += advance().value;
        if (k == TokenKind::Comma) s += ' ';
    }
    if (isObject) s += ' ';
    s += closeCh;
    return s;
}

